package com.jnapanam.sportszone.tournament.model;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="tournament_team_members")public class TournamentTeamMember{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="team_id")private TournamentTeam team;@Column(nullable=false,length=120)private String name;@Column(length=180)private String email;@Column(length=20)private String mobile;@Column(name="created_at",nullable=false)private Instant createdAt;protected TournamentTeamMember(){}public TournamentTeamMember(TournamentTeam t,String n,String e,String m){id=UUID.randomUUID();team=t;name=n.trim();email=clean(e);mobile=clean(m);createdAt=Instant.now();}public UUID getId(){return id;}public String getName(){return name;}public String getEmail(){return email;}public String getMobile(){return mobile;}private static String clean(String v){return v==null||v.isBlank()?null:v.trim();}}
